rule "gm extract admin event"
when
  has_field("message") &&
  contains(to_string($message.message), "httpd:") &&
  contains(to_string($message.message), "]: ")
then
  let msg = to_string($message.message);
  let u = regex("\\[([A-Za-z0-9_.-]+)\\]:\\s+([A-Za-z0-9_]+)", msg);
  set_field("gm_user", to_string(u["0"]));
  set_field("gm_event", to_string(u["1"]));
  let ip = regex("\\bip=([0-9.]+)", msg);
  set_field("gm_login_src", to_string(ip["0"]));
end

rule "ni extract module + summary"
when
  has_field("message") &&
  contains(to_string($message.message), "ni:")
then
  let msg = to_string($message.message);
  let m = regex("\\bni:([A-Za-z0-9_]+)\\[", msg);
  set_field("ni_module", to_string(m["0"]));
  let s = regex("([A-Za-z]+)\\s+Summary:\\s+([A-Za-z]+)", msg);
  set_field("ni_summary", to_string(s["0"]));
  set_field("ni_summary_status", to_string(s["1"]));
  let d = regex("\\(worker\\d+\\)\\s+([0-9.]+)/([A-Za-z]+)", msg);
  set_field("ni_target_ip", to_string(d["0"]));
  set_field("ni_scan_op",   to_string(d["1"]));
end
